@log_decorator
def select_treatment(trmt):
    return common_objects_ops.click_item(Xvi_MainPage.intuity_XVI_Default_Database_Treatment_List, trmt)

@log_decorator
def select_field(fld):
    return common_objects_ops.click_item(Xvi_MainPage.intuity_XVI_Default_Database_Field_List, fld)

@log_decorator
def load_image(pat, trmt, fld, img):
    if pat:
        patient_objects_ops.select_patient(pat)
    if trmt:
        select_treatment(trmt)
    if fld:
        select_field(fld)
    if img:
        image_objects_ops.select_image(img)

@log_decorator
def new_Patient_shortcut():
    main_window_focus()
    squishtest.nativeType('<Alt+P>')
    squishtest.snooze(.5)
    squishtest.nativeType('N')

@log_decorator
def open_Patient_by_buttons(patID: str):
    found = patient_objects_ops.locate_patient_in_list(patID)
    main_window_focus()
    if found:
        patient_objects_ops.click_edit_patient()
    else:
        patient_objects_ops.click_new_patient()
        pat_ops = patient_objects_ops.PatientOps()
        pat_ops.id = patID

@log_decorator
def open_Patient_by_shortcut(patID: str):
    found = patient_objects_ops.locate_patient_in_list(patID)
    main_window_focus()
    squishtest.nativeType('<Alt+P>')
    squishtest.snooze(.5)
    squishtest.nativeType('E' if found else 'N')
    if not found:
        pat_ops = patient_objects_ops.PatientOps()
        pat_ops.id = patID

@log_decorator
def get_xvi_app_version_from_ini():
    '''
    Gets the xvi app version
    '''
    major = ''
    minor = ''
    config = read_remote_ini_file(DataWrapper.ip, DataWrapper.port, 'C:\\XVI\\SRI.ini')
    version_section = 'Version'
    major_key = 'Major'
    minor_key = 'Minor'
    if version_section in config:
        major = config[version_section][major_key] if major_key in config[version_section] else ''
        minor = config[version_section][minor_key] if minor_key in config[version_section] else ''
    return major, minor

def open_remote_file(remote_machine_ip, port, remote_file):
    '''
    Open a remote file and get its content as a list of lines.Note the remote_file is still using its local path, for example, "c:\\xvi\\sri.ini".
    '''
    from remotesystem import RemoteSystem
    remote_system = RemoteSystem(remote_machine_ip, port)
    command = ["powershell.exe", "-Command", "Get-Content", f'{remote_file}']
    (exitcode, stdout, stderr)  = remote_system.execute(command)
    remote_system.close()
    file_contents = str(stdout).split('\n')
    return file_contents

def parse_ini_content(ini_obj):
    '''
    Parse the ini file content from either file object(obtained by open) or list of values of file contents.
    returns a dict of key, value pairs.
    '''
    config_data = {}
    current_section = None
    for line in ini_obj:
        line = line.strip()
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1]
            config_data[current_section] = {}
        elif '=' in line and current_section:
            key, value = line.split('=', 1)
            config_data[current_section][key.strip()] = value.strip()
    return config_data

def read_loca_ini_file(local_ini_file_path):
    '''
    This function is used to read the ini file from local path
    '''
    with open(local_ini_file_path, 'r') as file:
        return parse_ini_content(file)

def read_remote_ini_file(remote_machine_ip, port, remote_ini_file_path):
    '''
    This function is used to read the ini file from remote machine
    '''
    file_contents =  open_remote_file(remote_machine_ip, port, remote_ini_file_path)
    return parse_ini_content(file_contents)

@deco.set_separate_app_context(XVI_APP_NAME)
def is_synergistiq_mode_enabled() -> bool:
    '''
    Locates the open patient icon button from the top menu using image verification and click on it

    Returns:
        bool - Whether Synergistiq mode is enabled
    '''
    try:
        # Get the current python installation path
        python_install_path = sys.exec_prefix
        image_path = "Lib/site-packages/interops/libraries/xvi/interactions/images/xvi_synergistiq_label_image.png"
        synergistiq_label_image_path = os.path.abspath(os.path.join(
            python_install_path, image_path))

        search_options = {"timeout": 3000, 'tolerant': True, "threshold": 95.0}
        search_area = CommonActions.find_object(Xvi_MainPage.intuity_XVI_Default_Database_Window)

        synergistiq_enabled = CommonActions.wait_for_image_object(synergistiq_label_image_path, search_options, search_area)
        if synergistiq_enabled is not None:
            return True
        return False
    except Exception as e:
        print(f"Synergistiq label not found: {e}")
        return False

@deco.set_separate_app_context(application_name=XVI_APP_NAME)
def toggle_synergistiq_mode(enable_synergistiq_mode: bool = True) -> None:
    '''
    Function to toggle the Synergistiq mode by selecting the Mosaiq button from the main XVI dashboard

    Args:
        enable_synergistiq_mode (bool): True to enable Synergistiq mode, False to disable
    '''
    if (enable_synergistiq_mode and (is_synergistiq_mode_enabled() == False)):
        CommonActions.left_click_object_no_move(Xvi_MainPage.synergistiq_Pane)
        CommonActions.find_object(Xvi_MainPage.synergistiq_Label)
    elif ((enable_synergistiq_mode == False) and is_synergistiq_mode_enabled()):
        CommonActions.left_click_object_no_move(Xvi_MainPage.synergistiq_Pane)

@deco.set_separate_app_context(application_name=XVI_APP_NAME)
def is_user_logged_in(wait_timeout: int = 5000) -> bool:
    '''
    Function to check if a user is logged into XVI

    Args:
        wait_timeout (int): Time to wait for a user to be logged in

    Returns:
        bool - Whether a user is currently logged into XVI
    '''
    try:
        if CommonActions.find_object(Xvi_MainPage.intuity_XVI_Default_Database_Patient_List, wait_timeout) is not None:
            return True
        return False
    except FailedToFindObject:
        return False